fn solve(n: i8) -> Vec<i8> {
    // Number of complete 7-day weeks in n
    let full_weeks = n / 7;
    // Base days off from the complete weeks
    let base_off = full_weeks * 2;

    // Remaining days beyond the complete weeks
    let r = n % 7;

    // Minimum extra days off from the remainder:
    // if r > 5 we must include (r - 5) days off, otherwise 0
    let min_extra = if r > 5 { r - 5 } else { 0 };
    // Maximum extra days off from the remainder:
    // we can take at most 2 days off, but no more than r
    let max_extra = if r >= 2 { 2 } else { r };

    let min_off = base_off + min_extra;
    let max_off = base_off + max_extra;

    vec![min_off, max_off]
}

